-- 3. The next numbered code ----------------------------------------------------------------------
-- Null when the location doesn't number its codes. The INSERT … ON CONFLICT DO UPDATE takes the
-- counter row's lock until the caller's transaction ends, so parallel creates number one after
-- another; a rolled-back create gives its number back with the rollback (nothing else saw it).
CREATE FUNCTION kept.next_own_code(p_location uuid) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  s public.own_code_settings%ROWTYPE;
  n bigint;
  digits text;
  candidate text;
  tries integer := 0;
BEGIN
  IF p_location IS NULL
     OR NOT EXISTS (SELECT 1 FROM kept.writable_location_ids() w WHERE w = p_location) THEN
    RAISE EXCEPTION 'no such location of yours' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO s FROM public.own_code_settings o WHERE o.location_id = p_location;
  IF NOT FOUND OR NOT s.numbering THEN
    RETURN NULL;
  END IF;
  LOOP
    INSERT INTO public.own_code_counters AS c (location_id, prefix, last_number)
    VALUES (p_location, s.prefix, 1)
    ON CONFLICT (location_id, prefix) DO UPDATE SET last_number = c.last_number + 1
    RETURNING c.last_number INTO n;
    digits := n::text;
    -- lpad() would cut a number longer than the padding: GAR-10000 stays whole.
    IF char_length(digits) < s.pad THEN
      digits := lpad(digits, s.pad, '0');
    END IF;
    candidate := s.prefix || digits;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.legacy_codes g
                           WHERE g.location_id = p_location AND g.code = candidate);
    tries := tries + 1;
    IF tries >= 10000 THEN
      RAISE EXCEPTION 'every next number is taken' USING ERRCODE = 'check_violation',
        CONSTRAINT = 'own_code_numbers_taken';
    END IF;
  END LOOP;
  RETURN candidate;
END $$;
--> statement-breakpoint
REVOKE EXECUTE ON FUNCTION kept.next_own_code(uuid) FROM PUBLIC, kept_system;
--> statement-breakpoint

-- 4. A new confirmed thing is numbered -----------------------------------------------------------
-- A definer, so the counter's door is reached as its owner; it numbers only in a location the
-- writer may write (a job with no person numbers nothing). It runs at commit, so it reads the
-- thing as it is then: gone, trashed or back to a draft, it numbers nothing.
CREATE FUNCTION kept.number_new_thing() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  t record;
  code text;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.review_state = 'confirmed' THEN
    RETURN NULL;
  END IF;
  SELECT th.id, th.location_id INTO t FROM public.things th
   WHERE th.id = NEW.id AND th.review_state = 'confirmed' AND th.deleted_at IS NULL;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.own_code_settings o
                  WHERE o.location_id = t.location_id AND o.numbering) THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM kept.writable_location_ids() w WHERE w = t.location_id) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.legacy_codes g
              WHERE g.location_id = t.location_id AND g.source = 'own' AND g.thing_id = t.id) THEN
    RETURN NULL;
  END IF;
  code := kept.next_own_code(t.location_id);
  IF code IS NOT NULL THEN
    INSERT INTO public.legacy_codes (location_id, source, source_collection, code, thing_id)
    VALUES (t.location_id, 'own', '', code, t.id);
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE EXECUTE ON FUNCTION kept.number_new_thing() FROM PUBLIC, kept_app, kept_system;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER things_own_code_number
  AFTER INSERT OR UPDATE OF review_state ON public.things
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION kept.number_new_thing();
--> statement-breakpoint

-- 5. Removals reach phones -----------------------------------------------------------------------
-- The key is shared/src/sync.ts legacyCodeKey(): `<location>:<source>:<collection>:<code>`.
-- Definers: a tombstone is bookkeeping about the row that went or came, whoever wrote it (a person,
-- a door, a job), so it never depends on the writer's policies on sync_tombstones.
CREATE FUNCTION kept.tombstone_legacy_code() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  k text := OLD.location_id::text || ':' || OLD.source || ':' || OLD.source_collection || ':'
            || OLD.code;
BEGIN
  -- A location being deleted takes its tombstones with it; its phones drop it as revoked.
  IF NOT EXISTS (SELECT 1 FROM public.locations l WHERE l.id = OLD.location_id) THEN
    RETURN NULL;
  END IF;
  INSERT INTO public.sync_tombstones (location_id, entity_type, entity_id, entity_key)
  VALUES (OLD.location_id, 'legacy_code', md5(k)::uuid, k)
  ON CONFLICT (location_id, entity_type, entity_id) DO UPDATE SET updated_at = now();
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE EXECUTE ON FUNCTION kept.tombstone_legacy_code() FROM PUBLIC, kept_app, kept_system;
--> statement-breakpoint
CREATE TRIGGER legacy_codes_tombstone AFTER DELETE ON public.legacy_codes
  FOR EACH ROW EXECUTE FUNCTION kept.tombstone_legacy_code();
--> statement-breakpoint
CREATE FUNCTION kept.clear_code_tombstone_on_arrival() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
  DELETE FROM public.sync_tombstones z
   WHERE z.location_id = NEW.location_id AND z.entity_type = 'legacy_code'
     AND z.entity_id = md5(NEW.location_id::text || ':' || NEW.source || ':'
                           || NEW.source_collection || ':' || NEW.code)::uuid;
  RETURN NULL;
END $$;
--> statement-breakpoint
REVOKE EXECUTE ON FUNCTION kept.clear_code_tombstone_on_arrival() FROM PUBLIC, kept_app, kept_system;
--> statement-breakpoint
CREATE TRIGGER legacy_codes_tombstone_arrival AFTER INSERT OR UPDATE OF location_id ON public.legacy_codes
  FOR EACH ROW EXECUTE FUNCTION kept.clear_code_tombstone_on_arrival();
